package com.servicedesk360.controller;
import com.servicedesk360.dto.common.PageResponse; import com.servicedesk360.dto.task.*; import com.servicedesk360.service.TaskService; import jakarta.validation.Valid; import org.springframework.data.domain.Pageable; import org.springframework.data.web.PageableDefault; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/tasks") public class TaskController{private final TaskService service; public TaskController(TaskService service){this.service=service;} @GetMapping public PageResponse<TaskResponse> list(@PageableDefault(size=20,sort="createdAt")Pageable p){return service.list(p);} @PostMapping public TaskResponse create(@Valid @RequestBody TaskCreateRequest r){return service.create(r);} @PatchMapping("/{id}") public TaskResponse update(@PathVariable Long id,@RequestBody TaskUpdateRequest r){return service.update(id,r);} @PatchMapping("/{id}/status") public TaskResponse status(@PathVariable Long id,@Valid @RequestBody TaskStatusRequest r){return service.status(id,r);}}
